import random
from eywa.model import TypeSystem,AliasType,BoolType,CharType,IntType,StringType,EnumType,ArrayType,StructType,VoidType,int_width
from eywa.layout import compile_layout
class M: pass
def ref(t,path,c,slots):
 while isinstance(t,AliasType):t=t.target
 if isinstance(t,VoidType): return
 if isinstance(t,(BoolType,CharType)):
  n=c[0];c[0]+=1;slots.append([f'x{n}',list(path),1]);return
 if isinstance(t,IntType):
  n=c[0];c[0]+=1;slots.append([f'x{n}',list(path),int_width(t.bits)]);return
 if isinstance(t,EnumType):
  n=c[0];c[0]+=1;slots.append([f'x{n}',list(path),4]);return
 if isinstance(t,StringType):
  c[0]+=1
  for i in range(t.maxsize):
   n=c[0];c[0]+=1;slots.append([f'x{n}',list(path+[i]),1])
  return
 if isinstance(t,ArrayType):
  c[0]+=1
  for i in range(t.size):ref(t.element,path+[i],c,slots)
  return
 if isinstance(t,StructType):
  c[0]+=1
  for fn,ft in t.fields:ref(ft,path+[fn],c,slots)
  return
 raise Exception(type(t))
random.seed(123)
for trial in range(2000):
 # Generate DAG defs incrementally; each kind references earlier or primitive defs
 defs=[{'name':'B','kind':'bool'},{'name':'C','kind':'char'},{'name':'I','kind':'int','bits':random.randint(1,64)},{'name':'V','kind':'void'}]
 names=['B','C','I','V']
 for k in range(random.randint(0,15)):
  kind=random.choice(['string','enum','array','struct','alias','int'])
  name=f'T{k}'
  if kind=='string':d={'name':name,'kind':'string','maxsize':random.randint(0,4)}
  elif kind=='enum':d={'name':name,'kind':'enum','values':['a','b'][:random.randint(1,2)]}
  elif kind=='array':d={'name':name,'kind':'array','element':random.choice(names),'size':random.randint(0,3)}
  elif kind=='struct':d={'name':name,'kind':'struct','fields':[[f'f{j}',random.choice(names)] for j in range(random.randint(0,3))]}
  elif kind=='alias':d={'name':name,'kind':'alias','target':random.choice(names)}
  else:d={'name':name,'kind':'int','bits':random.randint(1,64)}
  defs.append(d);names.append(name)
 ts=TypeSystem(defs)
 m=M();m.params=[('p0',ts.get(random.choice(names))),('p1',ts.get(random.choice(names)))];m.result_name='r';m.result_type=ts.get(random.choice(names))
 # ensure result not void per domain? try void too separately okay
 lay=compile_layout(m,False)
 slots=[];c=[0];ref(m.params[0][1],['p0'],c,slots);ref(m.params[1][1],['p1'],c,slots);ref(m.result_type,['r'],c,slots)
 if lay.slots!=slots or lay.variables!=c[0]:
  print('MISMATCH',trial,defs,m.params,lay.slots,slots,lay.variables,c);break
else:print('layout all ok')
PY
